const test = require('node:test');
const assert = require('node:assert/strict');
const app = require('../lib/relative-link.cjs');
const path = require('node:path');
test('same resolved path and lexical traversal', () => {
  for (const [a,b,expected] of [
    ['/srv/docs','/srv/docs',''], ['/srv/docs/../docs/','/srv/docs',''],
    ['/srv/docs','/srv/assets/icon.svg','../assets/icon.svg'],
    ['/srv/docs','/srv/docs/guide/start.md','guide/start.md'],
    ['/srv/docs','/srv','..'], ['','','']
  ]) assert.equal(app.relativeLink(a,b),expected);
});
test('empty arguments mean the actual working directory', () => {
  const cwd = process.cwd();
  assert.equal(app.relativeLink('', cwd), '');
  assert.equal(app.relativeLink('', path.posix.join(cwd,'chapter')), 'chapter');
  assert.equal(app.relativeLink(path.posix.join(cwd,'chapter'), ''), '..');
  assert.equal(process.cwd(),cwd);
});

